#!/usr/bin/env python3
import ast,base64,os,subprocess,time,urllib.request
from pathlib import Path
ROOT=Path('/opt/bot-office')
AGENT=base64.b64decode('')
JS=base64.b64decode('').decode()
FUNC=base64.b64decode('').decode()
def patch(src,html,service):
 if 'BOT_OFFICE_OPT_V1' in src:raise ValueError('이미 적용되어 있습니다. 변경 없음.')
 if 'BOT_OFFICE_RISK_V1' not in src:raise ValueError('대비팀 업데이트부터 적용해야 합니다.')
 anchor="    data = {'observed_at':"
 marker="document.querySelector('#recentReports').innerHTML="
 if src.count(anchor)!=1 or html.count(marker)!=1 or html.count('</script>')!=1 or html.count('<div class="card bots">')!=1:raise ValueError('예상과 다른 버전입니다. 변경 없이 중단합니다.')
 addition="""    # BOT_OFFICE_OPT_V1
    try:
        optimization = json.loads(Path('/var/lib/bot-office/optimization.json').read_text())
    except (OSError, ValueError):
        optimization = None
"""
 updated=src.replace(anchor,addition+anchor).replace("'risk_report':risk_report,", "'optimization':optimization, 'risk_report':risk_report,")
 ast.parse(updated);ast.parse(AGENT)
 patched=html.replace(marker,JS+marker).replace('</script>',FUNC+'</script>')
 patched=patched.replace('<div class="card bots">','<section class="card" style="margin-top:22px"><div class="cardhead"><h2>최적화팀 · 자원 추이와 변경 전후 비교</h2><small>조회 전용</small></div><div id="optimizationBody" style="padding:20px">자원 표본 수집 대기</div></section><div class="card bots">')
 patched=patched.replace('대비팀 운영 보고만 실제이며','대비팀·최적화팀 운영 보고는 실제이며')
 run='ExecStart=/usr/bin/python3 /opt/bot-office/optimization_agent.py'
 prior='ExecStart=/usr/bin/python3 /opt/bot-office/risk_agent.py'
 if service.count(prior)!=1 or run in service:raise ValueError('예상과 다른 수집 서비스입니다.')
 service=service.replace(prior,prior+'\n'+run).replace('TimeoutStartSec=30','TimeoutStartSec=45')
 return updated,patched,service

def main():
 if os.geteuid()!=0:raise SystemExit('sudo python3 bot_office_optimization_update.py 로 실행하세요.')
 server=ROOT/'server.py';index=ROOT/'index.html';unit=Path('/etc/systemd/system/bot-office-inventory.service')
 src=server.read_text();html=index.read_text();service=unit.read_text()
 try:updated,patched,changed_service=patch(src,html,service)
 except ValueError as e:raise SystemExit(str(e))
 backup=ROOT/('backup_optimization_'+time.strftime('%Y%m%d_%H%M%S'));backup.mkdir()
 for name,text in (('server.py',src),('index.html',html),('inventory.service',service)):(backup/name).write_text(text)
 agent=ROOT/'optimization_agent.py';agent.write_bytes(AGENT);agent.chmod(0o644)
 subprocess.run(['/usr/bin/python3',str(agent)],check=True,timeout=20)
 try:
  for f,text in ((server,updated),(index,patched),(unit,changed_service)):
   tmp=f.with_suffix('.new');tmp.write_text(text);tmp.chmod(0o644);os.replace(tmp,f)
  subprocess.run(['systemctl','daemon-reload'],check=True)
  subprocess.run(['systemctl','start','bot-office-inventory.service'],check=True,timeout=55)
  subprocess.run(['systemctl','restart','bot-office.service'],check=True)
  for _ in range(10):
   try:
    with urllib.request.urlopen('http://127.0.0.1:8765/healthz',timeout=2) as r:
     if r.status==200:break
   except OSError:time.sleep(.5)
  else:raise RuntimeError('health check failed')
 except Exception:
  server.write_text(src);index.write_text(html);unit.write_text(service)
  subprocess.run(['systemctl','daemon-reload']);subprocess.run(['systemctl','restart','bot-office.service'])
  raise SystemExit('적용 실패: 기존 버전으로 복구했습니다. 오류 화면을 보내주세요.')
 print('완료: 최적화팀 연결 / 1분 표본 / 최대 24시간 보관')
 print('그래프: 약 1분 후 / 변경 전후 비교: 변경 이전·이후 각 5개 표본 필요')
 print('봇 변경·자동 삭제 없음. 사무실에 다시 로그인하세요.')
if __name__=='__main__':main()
